<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/music-analytics-v1.php';
require_login();
header('Cache-Control: no-store, private');
$user=current_user();$pdo=db();
if(!$pdo){http_response_code(503);exit('Database unavailable.');}
if(!music_workspace_resources_v330_schema_ready($pdo)){http_response_code(503);exit('Music Workspace database upgrade is required.');}
$requested=max(0,(int)($_GET['workspace']??0));
$workspace=music_workspace_resources_v330_resolve_active($pdo,$user,$requested);
if(!$workspace&&$requested>0){http_response_code(403);exit('Choose a Music Workspace that you can access.');}
if(!$workspace&&music_workspace_enabled_v320($user)){
    try{music_workspace_ensure_owner_v320($pdo,$user);$workspace=music_workspace_resources_v330_resolve_active($pdo,$user,$requested);}catch(Throwable $e){}
}
if(!$workspace){flash('error','Enable Music Workspace or join a Music Workspace Team to continue.');redirect(url('/plugins.php'));}
$workspaceId=(int)$workspace['id'];$ownerId=(int)$workspace['artist_user_id'];
$role=music_workspace_resources_v330_member_role($pdo,$workspaceId,(int)$user['id']);
$workspaces=music_workspace_resources_v330_accessible_workspaces($pdo,$user);
$counts=['tracks'=>0,'albums'=>0,'releases'=>0,'team'=>0];
foreach(['tracks'=>'artist_catalog_tracks_v181','albums'=>'artist_catalog_albums_v181'] as $key=>$table){
    if(table_exists($table)){try{$s=$pdo->prepare("SELECT COUNT(*) FROM {$table} WHERE workspace_id=?");$s->execute([$workspaceId]);$counts[$key]=(int)$s->fetchColumn();}catch(Throwable $e){}}
}
if(table_exists('release_plans')&&column_exists('release_plans','workspace_id')){try{$s=$pdo->prepare('SELECT COUNT(*) FROM release_plans WHERE workspace_id=?');$s->execute([$workspaceId]);$counts['releases']=(int)$s->fetchColumn();}catch(Throwable $e){}}
if(table_exists('artist_team_members')){try{$s=$pdo->prepare('SELECT COUNT(*) FROM artist_team_members atm INNER JOIN users u ON u.id=atm.member_user_id AND u.is_active=1 WHERE atm.artist_user_id=?');$s->execute([$ownerId]);$counts['team']=(int)$s->fetchColumn();}catch(Throwable $e){}}
$canManageSongs=music_workspace_resources_v330_can_manage($pdo,$workspaceId,'tracks',$user);
$canAnalytics=music_analytics_v1_can_view($pdo,$user,$workspaceId);
$metadataReady=music_song_metadata_v1_schema_ready($pdo);
if($metadataReady){$s=$pdo->prepare('SELECT COUNT(*) FROM artist_catalog_tracks_v181 t LEFT JOIN music_recordings_v1 m ON m.catalog_track_id=t.id AND m.workspace_id=t.workspace_id WHERE t.workspace_id=? AND m.archived_at IS NULL');$s->execute([$workspaceId]);$counts['tracks']=(int)$s->fetchColumn();}
$canListening=has_permission('artist_listening.access',$user);
$profileUrl=function_exists('artist_workspace_v181_profile_url')?artist_workspace_v181_profile_url($workspace):'';
$memberHeaderUser=$user;$memberHeaderTitle='Music Workspace';$memberHeaderSubtitle=(string)$workspace['workspace_name'].' · '.ucfirst($role?:'member');$memberHeaderActions='';
$scriptVersion=substr(hash_file('sha256',__DIR__.'/assets/js/music-analytics-v1.js'),0,12);
$styleVersion=substr(hash_file('sha256',__DIR__.'/assets/css/music-analytics-v1.css'),0,12);
$totalsScriptVersion=substr(hash_file('sha256',__DIR__.'/assets/js/music-listening-totals-v1.js'),0,12);
$totalsStyleVersion=substr(hash_file('sha256',__DIR__.'/assets/css/music-listening-totals-v1.css'),0,12);
$libraryUrl=url('/music-library.php?workspace='.$workspaceId);
