<section id="musicListeningTotals" class="mlt-panel" aria-labelledby="musicListeningTotalsTitle" data-listening-totals data-scope="workspace" data-workspace="<?= $workspaceId ?>" data-endpoint="<?= e(url('/api/music-listening-totals-v1.php')) ?>" data-csrf="<?= e(csrf_token()) ?>">
